const assistantRequests=new Map(),assistantRateLimit=(req,res,next)=>{const key=String(req.ip||req.socket.remoteAddress||"anonymous"),now=Date.now(),windowMs=10*60*1000,history=(assistantRequests.get(key)||[]).filter(time=>time>now-windowMs);if(history.length>=12)return res.status(429).json({error:"Please wait a few minutes before sending more assistant messages.",code:"AI_RATE_LIMITED"});history.push(now);assistantRequests.set(key,history);next()};
const ADMIN_COOKIE="solarious_admin_session",ADMIN_SESSION_SECONDS=8*60*60;
const safeEqual=(left,right)=>{const a=Buffer.from(String(left)),b=Buffer.from(String(right));return a.length===b.length&&timingSafeEqual(a,b)};
const signSession=payload=>createHmac("sha256",adminPassword).update(payload).digest("base64url");
const createSession=()=>{const payload=Buffer.from(JSON.stringify({username:adminUsername,expires:Date.now()+ADMIN_SESSION_SECONDS*1000,nonce:randomUUID()})).toString("base64url");return `${payload}.${signSession(payload)}`};
const cookieValue=(header,name)=>{for(const part of String(header||"").split(";")){const [key,...value]=part.trim().split("=");if(key===name)return decodeURIComponent(value.join("="))}return ""};
const verifySession=token=>{if(!token)return false;const separator=token.lastIndexOf(".");if(separator<1)return false;const payload=token.slice(0,separator),signature=token.slice(separator+1);if(!safeEqual(signature,signSession(payload)))return false;try{const data=JSON.parse(Buffer.from(payload,"base64url").toString("utf8"));return data.username===adminUsername&&Number(data.expires)>Date.now()}catch{return false}};
const sessionCookie=(value,maxAge=ADMIN_SESSION_SECONDS)=>`${ADMIN_COOKIE}=${encodeURIComponent(value)}; Path=/; HttpOnly; Max-Age=${maxAge}; SameSite=${process.env.NODE_ENV==="production"?"None":"Lax"}${process.env.NODE_ENV==="production"?"; Secure":""}`;
const asyncRoute=handler=>(req,res,next)=>Promise.resolve(handler(req,res,next)).catch(next);
const teamRoute=(operation,handler)=>asyncRoute(async(req,res,next)=>{try{return await handler(req,res,next)}catch(error){console.error("[team:error]",{operation,name:error instanceof Error?error.name:"UnknownError",message:error instanceof Error?error.message:String(error)});throw error}});
const admin=(req,res,next)=>{if(!verifySession(cookieValue(req.headers.cookie,ADMIN_COOKIE)))return res.status(401).json({error:"Admin authentication required"});next()};
const requiresDatabase=(req,res,next)=>{if(databaseStatus().connected)return next();return res.status(503).json({error:"Database is temporarily unavailable. Please retry shortly."})};
app.use("/api",(req,res,next)=>["/health","/admin/login","/admin/session","/admin/logout"].includes(req.path)?next():requiresDatabase(req,res,next));
