const safeFileName=value=>basename(String(value||"file")).replace(/[^a-zA-Z0-9._-]/g,"_");
const serviceError=(message,stage,status=502,details={})=>Object.assign(new Error(message),{status,stage,...details});
const cloudUpload=async(source,options={})=>{const {errorStage="storage_upload",errorMessage="Cloud storage upload failed",...uploadOptions}=options;if(cloudinaryConfigured){try{return await new Promise((resolve,reject)=>{const stream=cloudinary.uploader.upload_stream(uploadOptions,(error,result)=>error?reject(error):result?resolve(result):reject(new Error("Cloud storage returned no upload result.")));source.once("error",error=>{stream.destroy(error);reject(error)});source.pipe(stream)})}catch(error){console.error("[cloudinary:upload:error]",{stage:errorStage,name:error?.name||"Error",status:Number(error?.http_code)||502});throw serviceError(errorMessage,errorStage,Number(error?.http_code)||502,{code:"CLOUDINARY_UPLOAD_FAILED"})}}if(!localUploadsEnabled)throw serviceError("Cloud storage is not configured. Configure CLOUDINARY_URL on the backend service.","storage_configuration",503);await mkdir(localUploadDir,{recursive:true});const requested=safeFileName(uploadOptions.public_id||"upload"),extension=extname(requested)||String(uploadOptions.format?`.${uploadOptions.format}`:""),stem=extension?requested.slice(0,-extension.length):requested,fileName=`${stem}-${randomUUID()}${extension}`,target=join(localUploadDir,fileName);await pipeline(source,createWriteStream(target,{flags:"wx"}));return{secure_url:`/api/files/${encodeURIComponent(fileName)}`,public_id:`local:${fileName}`}};
const destroyUpload=async(storageId,options={})=>{if(!storageId)return;if(storageId.startsWith("local:")){if(!localUploadsEnabled)return;await rm(join(localUploadDir,safeFileName(storageId.slice(6))),{force:true});return}if(!cloudinaryConfigured)throw serviceError("Cloud storage is not configured.","storage_configuration",503);try{await cloudinary.uploader.destroy(storageId,options)}catch(error){console.error("Cloudinary delete failed",{stage:"storage_delete",name:error?.name||"Error",message:error?.message||"Unknown storage error"});throw serviceError("Cloud storage delete failed","storage_delete")}};
const memoryUpload=multer({storage:multer.memoryStorage(),limits:{fileSize:8*1024*1024},fileFilter(_req,file,done){if(!["image/jpeg","image/png","image/webp","image/avif"].includes(file.mimetype))return done(serviceError("Image must be a JPG, PNG, WebP or AVIF file.","validation",415));done(null,true)}});
const imageUpload=field=>(req,res,next)=>memoryUpload.single(field)(req,res,error=>{if(!error)return next();if(error.code==="LIMIT_FILE_SIZE")return next(serviceError("Image must be 8 MB or smaller.","validation",413));next(error)});
