async function runDailyCreative(req,res){if(!process.env.CRON_SECRET||req.get("authorization")!=="Bearer "+process.env.CRON_SECRET)return res.status(401).json({error:"Unauthorized"});const date=businessDate();const existing=await Creative.findOne({creativeDate:date,generationType:"automatic"});if(existing?.status==="completed")return res.json({ok:true,skipped:"already-generated"});const item=await generateAndPersist(date,"automatic",existing,0);res.status(201).json({ok:true,id:String(item._id),creative:creative(item.toObject())});}
